import data from "../../data/territory-catalog.json";

/**
 * The areas that are OPEN: a real boundary, a validated road mask and a conquest threshold worked out from that mask's own analysis.
 * Small, bundled and synchronous on purpose: rules, Home and the run screen ask "is it open, and what does conquest take there?" without
 * fetching anything. Every other area (COMING_SOON or NOT_OPEN, with its reason) is in the lazily loaded `public/geo/bd/territories.json`.
 *
 * Generated by `tools/territory-mask/catalog.ts` from the committed analyses and checked against the committed masks by a test.
 * Never edit by hand: a threshold here must match the area's mask, and `firestore.rules` is generated from the same file.
 */
export interface OpenArea {
  name: string;
  /** Share of eligible cells that conquers it (an area-specific figure, 40 to 80). */
  percent: number;
  eligibleCells: number;
  requiredCells: number;
  /** Real length of the different walkable streets inside the area (km, from the OpenStreetMap analysis), and its land area (km²). */
  streetKm: number | null;
  areaKm2: number | null;
  maskVersion: string;
  /** Boundary chunk (`/geo/bd/<chunk>.json`) holding the area's display boundary. */
  chunk: string;
}

export const OPEN_CATALOG: Readonly<Record<string, OpenArea>> = (data as { areas: Record<string, OpenArea> }).areas;

export const DEFAULT_THRESHOLD_PERCENT = 80;

export const isOpenArea = (id: string | null | undefined): boolean => Boolean(id && Object.prototype.hasOwnProperty.call(OPEN_CATALOG, id));
export const openAreaOf = (id: string | null | undefined): OpenArea | null => (id && isOpenArea(id) ? OPEN_CATALOG[id] : null);
/** The conquest threshold of an area in whole percent. Unknown areas get the default; they cannot be played anyway. Integer, so cell counts are exact. */
export const thresholdPercentOf = (id: string): number => (isOpenArea(id) ? OPEN_CATALOG[id].percent : DEFAULT_THRESHOLD_PERCENT);

/** "135.8 km of streets · 7.1 km²": how big the area is, from the same data its conquest is measured on. Empty if unknown. */
export function sizeLabelOf(id: string | null | undefined): string {
  const a = openAreaOf(id);
  if (!a) return "";
  const parts: string[] = [];
  if (a.streetKm) parts.push(`${a.streetKm >= 100 ? Math.round(a.streetKm) : a.streetKm.toFixed(1)} km of streets`);
  if (a.areaKm2) parts.push(`${a.areaKm2 >= 100 ? Math.round(a.areaKm2) : a.areaKm2.toFixed(1)} km²`);
  return parts.join(" · ");
}
